@SuppressWarnings("unchecked")
void calc() {
    int[] ns = nextInts();
    int N = ns[0], M = ns[1];
    UnionFind uf = new UnionFind(N);
    int[] A = nextInts();
    List<int[]>[] no = new List[200001];
    Arrays.setAll(no, i -> new ArrayList<>());
    for (int i = 0; i < M; i++) {
        int[] uv = nextInts();
        int u = uv[0] - 1, v = uv[1] - 1;
        if (A[u] == A[v]) uf.connect(u, v);
        if (A[u] < A[v]) no[A[u]].add(new int[] {u, v});
        if (A[u] > A[v]) no[A[v]].add(new int[] {v, u});
    }

    int[] dp = new int[N];
    Arrays.fill(dp, -1);
    int r0 = uf.getRoot(0);
    dp[r0] = 1;
    for (var n : no) {
        for (int[] uv : n) {
            int u = uf.getRoot(uv[0]), v = uf.getRoot(uv[1]);
            if (dp[u] > 0) dp[v] = Math.max(dp[v], dp[u] + 1);
        }
    }
    System.out.println(dp[uf.getRoot(N - 1)]);
}
